package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="categoria_financeira",schema="adm_eclesial") public class CategoriaFinanceira { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(nullable=false,unique=true,length=50) String codigo; @Column(nullable=false,length=150) String nome; @Column(length=30) String tipo; @Column(nullable=false) boolean ativo; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public String getCodigo(){return codigo;} public String getNome(){return nome;} public String getTipo(){return tipo;} public boolean getAtivo(){return ativo;} public void setCodigo(String v){codigo=v;} public void setNome(String v){nome=v;} public void setTipo(String v){tipo=v;} public void setAtivo(boolean v){ativo=v;} }